Consider this BST insert that sends equal keys to the left:

```python
class Node:
    def __init__(self, v):
        self.v=v; self.l=None; self.r=None

def insert(t, x):
    if not t: return Node(x)
    if x <= t.v:
        t.l = insert(t.l, x)
    else:
        t.r = insert(t.r, x)
    return t

def inorder(t, out):
    if not t: return
    inorder(t.l, out)
    out.append(t.v)
    inorder(t.r, out)

root=None
for k in [7, 9, 7, 5, 8]:
    root = insert(root, k)
res=[]
inorder(root, res)
print(res)
```
